<?php

declare(strict_types=1);

namespace HostingPal\WhmApiClient\Response;

use HostingPal\WhmApiClient\Exception\InvalidResponseException;
use LogicException;

/**
 * Validate and normalize a decoded JSON payload against a generated type spec.
 *
 * Type specs are generated by tools/api-map from the pinned schema plus the
 * evidence-bound overlay. Operation-level spec keys are described on
 * Api\Engine\OperationSpec. Values are validated without guessing: an observed
 * wire variant is accepted only when the spec lists it in "accept", and it is
 * then normalized to the declared type when that is lossless.
 *
 * Grammar: a type spec is an array with a "type" and optional keys.
 *
 * - string: a JSON string, returned unchanged. An explicit "literal" string
 *   constrains it to that exact value; this is an opt-in overlay constraint,
 *   never inferred from upstream enums.
 * - int: a JSON integer. "accept" 'numeric-string' also admits a canonical
 *   decimal string (optional minus, no leading zeros, within PHP int range).
 *   The separate 'integral-fixed-point-string' opt-in admits that same integer
 *   part followed by a dot and one or more zeros. Its integer part is checked by
 *   an exact string/int roundtrip; negative zero and overflow fail. Conversion
 *   strips only the zero fraction, without floats, rounding or precision loss.
 * - number: an int or finite float. "accept" 'numeric-string' also admits a
 *   string of the form [+-]?digits(.digits)?; with "preserve" => true (number
 *   only) the matched string is returned unchanged. Otherwise it is normalized as
 *   json_decode() normalizes the same digits written as a JSON number: an integer
 *   form within the PHP int range becomes an int (leading zeros and a plus sign
 *   dropped, "-0" as 0), and every other form becomes a float, so precision may be
 *   lost exactly as for a JSON number outside the int range, which decodes as a
 *   float and is accepted as one.
 * - bool: a JSON boolean. "accept" 'int-flag' admits 0/1 and 'string-flag'
 *   admits "0"/"1"; both normalize to bool.
 * - flag: the integer 0 or 1. "accept" 'string-flag' admits "0"/"1" and 'bool'
 *   admits booleans; both normalize to 0|1. Explicit 'empty-string' admits only
 *   the exact empty string and preserves it as '', without flag coercion.
 * - mixed: any decoded JSON value, including null, converted to arrays.
 * - list: a JSON array whose elements all match "items" (a type spec).
 * - map: a JSON object whose values all match "values" (a type spec); numeric
 *   keys stay integer keys. An empty JSON array [] is an empty map.
 * - object: "fields" (name => type spec) are validated in declared order and
 *   returned under their names (numeric names become integer keys); fields
 *   named in "required" must be present. An optional "values" type spec validates
 *   and preserves undeclared fields; without it, unknown payload fields are dropped.
 *   An empty JSON array [] is an empty object when nothing is required.
 * - union: "anyOf" (nonempty list of type specs); the first branch that
 *   validates wins and partial branch results are discarded.
 *
 * Any variant not listed in "accept" fails. Null is rejected unless the spec has
 * "nullable" => true, is "mixed", or is a union with a branch that accepts null.
 *
 * A payload mismatch raises InvalidResponseException through the supplied
 * reader, so the response snapshot travels with the failure. A malformed spec
 * is a generator defect and raises LogicException; Api\Engine\SpecChecker checks
 * this grammar completely before a generated operation dispatches its request.
 *
 * @internal
 */
final class ShapeValidator
{
    /**
     * Validate one value and return its normalized form.
     *
     * Null is accepted when the spec is nullable, for "mixed", and for a union
     * with a branch that accepts null. Accepted wire variants
     * listed in the spec's "accept" normalize to the declared type, except an
     * explicitly accepted empty string is preserved.
     *
     * @param array<mixed> $type
     * @throws InvalidResponseException If the value does not satisfy the spec.
     * @throws LogicException If the spec itself is malformed.
     */
    public static function value(mixed $value, array $type, PayloadReader $read): mixed
    {
        if ($value === null) {
            return self::nullValue($type, $read);
        }

        $accept = self::accept($type);

        return match ($type['type'] ?? null) {
            'string' => self::string($value, $type, $read),
            'int' => self::int($value, $accept, $read),
            'number' => self::number($value, $accept, ($type['preserve'] ?? false) === true, $read),
            'bool' => self::bool($value, $accept, $read),
            'flag' => self::flag($value, $accept, $read),
            'mixed' => $read->json($value),
            'list' => $read->listOf(
                $value,
                static fn (mixed $item): mixed => self::value($item, self::child($type, 'items'), $read),
            ),
            'map' => self::map($value, self::child($type, 'values'), $read),
            'object' => self::object($value, $type, $read),
            'union' => self::union($value, $type, $read),
            default => throw new LogicException('Unsupported type spec.'),
        };
    }

    /** @param array<mixed> $type */
    private static function string(mixed $value, array $type, PayloadReader $read): string
    {
        $value = $read->string($value);
        if (array_key_exists('literal', $type)) {
            if (!is_string($type['literal'])) {
                throw new LogicException('Invalid string literal spec.');
            }
            if ($value !== $type['literal']) {
                $read->fail();
            }
        }

        return $value;
    }

    /**
     * Decide whether JSON null satisfies the spec.
     *
     * @param array<mixed> $type
     */
    private static function nullValue(array $type, PayloadReader $read): mixed
    {
        if (($type['nullable'] ?? false) === true || ($type['type'] ?? null) === 'mixed') {
            return null;
        }

        return ($type['type'] ?? null) === 'union' ? self::union(null, $type, $read) : $read->fail();
    }

    /**
     * Read a nested spec, failing loudly when the generator omitted it.
     *
     * @param array<mixed> $type
     * @return array<mixed>
     */
    private static function child(array $type, string $key): array
    {
        $child = $type[$key] ?? null;
        if (!is_array($child)) {
            throw new LogicException('Type spec is missing "' . $key . '".');
        }

        return $child;
    }

    /**
     * Validate a JSON object map; an empty JSON array is an empty map.
     *
     * @param array<mixed> $valueType
     * @return array<array-key, mixed>
     */
    private static function map(mixed $value, array $valueType, PayloadReader $read): array
    {
        if ($value === []) {
            return [];
        }

        $result = [];
        foreach (get_object_vars($read->object($value)) as $key => $item) {
            $result[$key] = self::value($item, $valueType, $read);
        }

        return $result;
    }

    /**
     * Validate declared fields first, then opt-in extra values in their wire order.
     *
     * @param array<mixed> $type
     * @return array<array-key, mixed>
     */
    private static function object(mixed $value, array $type, PayloadReader $read): array
    {
        $fields = $type['fields'] ?? [];
        $required = $type['required'] ?? [];
        if (!is_array($fields) || !is_array($required)) {
            throw new LogicException('Invalid object type spec.');
        }

        $valueType = array_key_exists('values', $type) ? self::child($type, 'values') : null;
        if ($value === [] && $required === []) {
            return [];
        }

        $object = $read->object($value);
        $result = [];
        foreach ($fields as $name => $fieldType) {
            if (!is_array($fieldType)) {
                throw new LogicException('Invalid field type spec.');
            }

            $name = (string) $name;
            if (property_exists($object, $name)) {
                $result[$name] = self::value($object->{$name}, $fieldType, $read);
            } elseif (in_array($name, $required, true)) {
                $read->fail();
            }
        }

        if ($valueType !== null) {
            foreach (get_object_vars($object) as $name => $item) {
                if (!array_key_exists($name, $fields)) {
                    $result[$name] = self::value($item, $valueType, $read);
                }
            }
        }

        return $result;
    }

    /**
     * Return the first branch that validates; partial branch results are discarded.
     *
     * @param array<mixed> $type
     */
    private static function union(mixed $value, array $type, PayloadReader $read): mixed
    {
        $options = $type['anyOf'] ?? null;
        if (!is_array($options) || $options === []) {
            throw new LogicException('Invalid union type spec.');
        }

        foreach ($options as $option) {
            if (!is_array($option)) {
                throw new LogicException('Invalid union type spec.');
            }

            try {
                return self::value($value, $option, $read);
            } catch (InvalidResponseException) {
                continue;
            }
        }

        return $read->fail();
    }

    /**
     * Read the accepted wire variants of a spec.
     *
     * @param array<mixed> $type
     * @return list<string>
     */
    private static function accept(array $type): array
    {
        $accept = $type['accept'] ?? [];

        return is_array($accept) ? array_values(array_filter($accept, is_string(...))) : [];
    }

    /** @param list<string> $accept */
    private static function int(mixed $value, array $accept, PayloadReader $read): int
    {
        if (is_int($value)) {
            return $value;
        }

        if (
            in_array('numeric-string', $accept, true)
            && is_string($value)
            && preg_match('/\A-?(?:0|[1-9][0-9]*)\z/', $value) === 1
            && (string) (int) $value === $value
        ) {
            return (int) $value;
        }

        if (
            in_array('integral-fixed-point-string', $accept, true)
            && is_string($value)
            && preg_match('/\A(-?(?:0|[1-9][0-9]*))\.0+\z/', $value, $parts) === 1
            && (string) (int) $parts[1] === $parts[1]
        ) {
            return (int) $parts[1];
        }

        return $read->fail();
    }

    /** @param list<string> $accept */
    private static function number(mixed $value, array $accept, bool $preserve, PayloadReader $read): int|float|string
    {
        if (is_int($value) || (is_float($value) && is_finite($value))) {
            return $value;
        }

        if (
            in_array('numeric-string', $accept, true)
            && is_string($value)
            && preg_match('/\A[+-]?[0-9]+(?:\.[0-9]+)?\z/', $value) === 1
            && is_finite((float) $value)
        ) {
            if ($preserve) {
                return $value;
            }

            if (str_contains($value, '.')) {
                return (float) $value;
            }

            $sign = $value[0] === '-' ? '-' : '';
            $digits = ltrim(ltrim($value, '+-'), '0');
            $canonical = $digits === '' ? '0' : $sign . $digits;

            // Outside the int range json_decode() yields a float for the same digits.
            return (string) (int) $canonical === $canonical ? (int) $canonical : (float) $canonical;
        }

        return $read->fail();
    }

    /** @param list<string> $accept */
    private static function bool(mixed $value, array $accept, PayloadReader $read): bool
    {
        if (is_bool($value)) {
            return $value;
        }

        if (in_array('int-flag', $accept, true) && ($value === 0 || $value === 1)) {
            return $value === 1;
        }

        if (in_array('string-flag', $accept, true) && ($value === '0' || $value === '1')) {
            return $value === '1';
        }

        return $read->fail();
    }

    /**
     * Normalize flag variants while preserving an explicitly accepted empty string.
     *
     * @param list<string> $accept
     * @return ''|0|1
     */
    private static function flag(mixed $value, array $accept, PayloadReader $read): int|string
    {
        if ($value === 0 || $value === 1) {
            return $value;
        }

        if (in_array('string-flag', $accept, true) && ($value === '0' || $value === '1')) {
            return $value === '1' ? 1 : 0;
        }

        if (in_array('empty-string', $accept, true) && $value === '') {
            return '';
        }

        if (in_array('bool', $accept, true) && is_bool($value)) {
            return $value ? 1 : 0;
        }

        return $read->fail();
    }
}
